typedef struct { bool ok; int value; int errs[8]; size_t nerrs; } parsed_int;

parsed_int parse_age(const char *s);      /* one independent effect */
parsed_int parse_weight(const char *s);

parsed_int combine_body(const char *age, const char *weight) {
    parsed_int a = parse_age(age);        /* evaluated independently */
    parsed_int w = parse_weight(weight);
    if (!a.ok || !w.ok)
        return (parsed_int){ .ok = false, .nerrs = errs_join(a.errs, a.nerrs, w.errs, w.nerrs, ...) };
    return (parsed_int){ .ok = true, .value = 100 * a.value + w.value };
}
